args.sql:
WITH scored AS (
 SELECT *, atmostransparency * (1 - humidityrate / 100.0) * (1 - 0.02 * windspeedms) AS aoi
 FROM observatories
), classified AS (
 SELECT *, COALESCE(aoi > 0.85 AND lunarstage IN ('New', 'First Quarter') AND lunardistdeg > 45 AND solarstatus IN ('Low', 'Moderate'), FALSE) AS is_optimal_window
 FROM scored
)
SELECT is_optimal_window, COUNT(*) AS station_count, ROUND(AVG(aoi), 3) AS avg_aoi
FROM classified GROUP BY is_optimal_window;

